def git(work,*args):return subprocess.check_output(['git','-C',str(work),*args],text=True)

def staged_identity(work):
    """Semantic identity of staged index entries: mode, blob id, stage, path.

    ``git ls-files --stage`` is content-addressed (blob object ids) and excludes
    the index stat-cache bytes (mtime/size/ino/dev/uid/gid) that Git stores for
    fast refresh. Those bytes change without any semantic staging change, so the
    raw ``.git/index`` bytes or ``ls-files --debug`` must not be used here.
    """
    return git(work,'ls-files','--stage')

